(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sk"] = {"ui":{"skip":"Preskočiť na obsah","back":"← Späť na AI-gile","lang.button":"Jazyk: {name}","lang.dialog":"Vyber jazyk","lang.search":"Hľadať jazyky","lang.none":"Žiadny jazyk nezodpovedá","lang.notYet":"{name} ešte nie je preložený","theme.aria":"Prepnúť medzi svetlou a tmavou témou","theme.toLight":"Prepnúť na svetlú tému","theme.toDark":"Prepnúť na tmavú tému","words.underline":"Podčiarknuť tieto slová na stránke","words.underlineHelp":"Prejdi myšou nad bodkovane podčiarknuté slovo alebo naň ťukni a uvidíš, čo znamená.","index.title":"AI-gile: tvoj AI vývojársky tím na jednej tabuli","index.description":"AI-gile je kanban tabuľa pre tímy AI programátorov. Pracujú, kým spíš; ty dostaneš jednu krátku kôpku vecí na rozhodnutie, otestovanie a schválenie.","hero.logoAlt":"Ikona tabule AI-gile","hero.h1.html":"Tvoj AI vývojársky tím na jednej&nbsp;tabuli.","hero.alpha":"🐣 Uzavretá pre-alfa","hero.alphaTitle":"Skorá a nedokončená verzia: vďaka, že ju skúšaš!","hero.lede":"Stavajú, kým spíš. Ráno ťa čaká jedna krátka kôpka: pár otázok, pár vecí na otestovanie, jeden-dva fialové diamanty. Klikneš, schválíš a vrátiš sa ku káve.","dl.windows":"Aplikácia pre Windows","dl.browser":"Spustiť v prehliadači","dl.soon":"Čoskoro","dl.notify":"🔔 Daj mi vedieť, keď sa otvorí","dl.notifySmall":"Alfa alebo beta","hero.secondary":"Agilne, ale tím nikdy nepotrebuje ranný stand-up s kávou. (Stand-upy aj tak robia.)","pitch.h2":"AI-gile v toľkých slovách, koľko chceš","pitch.lede":"Vyber dĺžku, od jedného slova po 144. Každá dĺžka je samostatný popis napísaný práve pre ňu. Potiahni posuvník alebo použi šípky.","pitch.rangeLabel":"Dĺžka v slovách","pitch.dice":"🎲 iná verzia","pitch.words.one":"{n} slovo","pitch.words.other":"{n} slov","pitch.letters.one":"{n} písmeno","pitch.letters.other":"{n} písmen","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakov","count.line.html.one":"{n} karta je práve na tabuli","count.line.html.other":"{n} kariet je práve na tabuli","features.aria":"Čo robí","f.pile.h":"Jedna kôpka pre teba","f.pile.html":"<b>Pre teba</b> obsahuje všetko, čo čaká na teba, naprieč všetkými projektmi: otázky, veci na otestovanie, úlohy, ktoré zvládne len človek. Tvoj rad ti povie, čo je na rade a koľko to potrvá.","f.sleep.h":"Tímy, ktoré pracujú, kým spíš","f.sleep.p":"Každý projekt má vedúceho a tím AI agentov. Napíš komentár ku karte a tím sa zobudí, odvedie prácu a vráti ti ju s krokmi, ktoré zvládne aj unavený človek.","f.tester.h":"Najprv kontroluje AI tester","f.tester.p":"Skôr než sa čokoľvek dostane k tebe, tester prejde kroky v kópii aplikácie a ukáže, čo videl, so snímkou obrazovky. Prelistuj tie, čo prešli, a schváľ jedným klikom.","f.proof.h":"Dôkazy, nie sľuby","f.proof.p":"Každé odovzdanie ukazuje, čo sa zmenilo: súbory, rozdiely, snímky obrazovky. Nemusíš otvárať každú aplikáciu, aby si zistil, či je hotovo.","f.chat.h":"Chat so svojimi vedúcimi","f.chat.p":"Lišta ako na Discorde: jedna ikona na projekt, fialové diamanty pri tom, čo potrebuje teba. Napíš vedúcemu nápad; premení ho na karty a plán s tlačidlom ✅ Ísť na to.","f.tidy.h":"Upratuje si po sebe","f.tidy.p":"Súvisiace karty sa zlúčia, zmätené názvy sa opravia a kontrola tokenov udržiava kód štíhly. Menej vecí na prepínanie, menej na premýšľanie.","f.private.h":"Tvoje, na tvojom počítači","f.private.li1":"Tabuľa beží na tvojom vlastnom stroji a odpovedá len tebe.","f.private.li2":"Súkromné správy medzi ľuďmi sú šifrované end-to-end.","f.private.li3":"Žiadne účty, žiadne sledovače, žiadne cookies.","f.lang.h":"Vo tvojom jazyku","f.lang.p":"Vyše 120 jazykov, od holandčiny, walesčiny a japončiny až po pirátčinu, Yodu a klingončinu, s rýchlym prepnutím späť do angličtiny pre vývojárske slová.","tl.aria":"Časová os od prvého rozhovoru po plán","tl.h2":"Od prvého rozhovoru po to, čo príde","tl.lede":"Skutočné dátumy a časy vo tvojom časovom pásme. Po dnešku je to plán, bez sľubovaných dátumov.","tl.today":"Dnes","tl.planned":"plánované","tl.cards.one":"{n} karta","tl.cards.other":"{n} kariet","join.h2":"Pridaj sa","join.lede":"AI-gile stavia jeden malý človek a veľa trpezlivých agentov. Zatiaľ je súkromné, v uzavretej alfe s priateľmi. Chceš si ho vyskúšať, keď sa otvorí?","join.btn":"Prejaviť záujem","join.small":"Napíšeme ti e-mail, nič iné","footer.tag":"AI-gile. Žiadne sledovače, žiadne cookies, žiadna stand-up káva.","footer.licence":"Podniková licencia","footer.status":"Stav","footer.privacy":"Čo uchovávame","form.sending":"Odosiela sa…","form.failed":"Nevyšlo to: skús to neskôr.","form.offline":"AI-gile sa nepodarilo kontaktovať: skús to neskôr.","form.keep":"Použijeme to len na to, aby sme ti odpovedali, potom to zmažeme. Žiadne sledovače, žiadne cookies.","form.keepLink":"Čo uchovávame","interest.title":"AI-gile: daj mi vedieť, keď sa otvorí alfa","interest.description":"Nechaj nám e-mail a dáme ti vedieť, keď sa otvorí uzavretá alfa alebo beta AI-gile.","interest.h1":"🔔 Daj mi vedieť, keď sa otvorí","interest.lede":"AI-gile je v uzavretej pre-alfe. Nechaj nám e-mail a napíšeme ti raz, keď bude pre teba miesto.","interest.email":"Tvoj e-mail","interest.which":"Ktorý test?","interest.alpha":"Uzavretá alfa: skorá, drsná, veľa zmien","interest.beta":"Beta: stabilnejšia, neskôr","interest.both":"Ktorýkoľvek, podľa toho, čo bude skôr","interest.submit":"Zapísať ma do zoznamu","interest.thanks":"Vďaka! Si v zozname.","licence.title":"AI-gile: podniková licencia","licence.description":"Používaš AI-gile vo svojej firme? Požiadaj o bezplatnú podnikovú licenciu.","licence.h1":"📜 Podniková licencia","licence.lede":"Používaš AI-gile v práci? Povedz nám, kto si a čo robíš. Ak to robí svet lepším, licencia je zadarmo.","licence.company":"Firma","licence.website":"Web","licence.what":"Čo robíš","licence.how":"Ako to pomáha svetu","licence.email":"E-mail","licence.submit":"Požiadať","licence.thanks":"Vďaka! Odpovieme e-mailom.","status.title":"Stav AI-gile","status.h1":"Stav AI-gile","status.quiet":"Všetko pokojné","status.intro":"Funguje AI-gile práve teraz? Táto stránka každých 5 minút kontroluje web, zdieľanie tabúľ, hovory a sťahovanie.","status.up":"Funguje (odpoveď za {ms} ms)","status.slow":"Bez odpovede pri poslednej kontrole, skúšam znova","status.down":"Nefunguje: bez odpovede pri posledných dvoch kontrolách","status.svc.web":"Web","status.svc.web.offers":"Táto stránka: čo je AI-gile a formulár na prejavenie záujmu","status.svc.boards":"Zdieľanie tabúľ","status.svc.boards.offers":"Verejné tabule, správy medzi priateľmi a pozvánky","status.svc.calls":"Hovory","status.svc.calls.offers":"Hlas, video a zdieľanie obrazovky v AI-gile","status.svc.download":"Sťahovanie","status.svc.download.offers":"Inštalátor pre Windows a odkazy na pozvánky","status.checking":"Kontroluje sa…","status.offline":"Služba stavu je teraz nedostupná (skúšam znova)","status.updated":"aktualizované {ago}","status.justNow":"práve teraz","status.min":"pred {n} min","status.hours":"pred {n} h","status.days":"pred {n} d","privacy.title":"AI-gile: čo uchovávame","privacy.h1":"Čo uchovávame","privacy.lede":"Stručne: len to, čo nám pošleš, a nie nadlho.","privacy.only":"Len to, čo nám pošleš: to, čo napíšeš do formulára, napríklad svoj e-mail. Nič iné o tebe.","privacy.sealed":"Je to zapečatené, takže náš server to nedokáže prečítať: v tvojom prehliadači ešte pred odoslaním (v staršom prehliadači hneď po doručení). Otvoriť to vie len naša vlastná tabuľa.","privacy.server":"Zo servera sa to zmaže hneď, ako to dorazí na našu tabuľu. Čokoľvek, čo tam zostane aj po 30 dňoch, sa aj tak zmaže.","privacy.board":"Na našej tabuli to necháme len dovtedy, kým ti neodpovieme, potom to zmažeme aj tam.","privacy.none":"Žiadne sledovače, žiadne cookies, žiadna analytika.","privacy.local":"Tvoj jazyk a voľba svetlej či tmavej témy zostávajú v tvojom prehliadači. Nikdy sa nám neposielajú.","privacy.ask":"Chceš, aby to zmizlo skôr? Odpovedz na náš e-mail a napíš nám to.","live.h2":"Sledujte, ako sa to stavia, naživo","live.caption":"Každá karta je skrytá: vidíte tvar práce, nie slová.","live.watching.one":"naživo: sleduje {n}","live.watching.other":"naživo: sledujú {n}","live.last.now":"Posledná karta presunutá práve teraz","live.last.min.one":"Posledná karta presunutá pred {n} minútou","live.last.min.other":"Posledná karta presunutá pred {n} minútami","live.last.hour.one":"Posledná karta presunutá pred {n} hodinou","live.last.hour.other":"Posledná karta presunutá pred {n} hodinami","live.last.day.one":"Posledná karta presunutá pred {n} dňom","live.last.day.other":"Posledná karta presunutá pred {n} dňami","live.offline":"Živá tabuľa si dáva pauzu. Skúste to čoskoro znova.","live.cols":"Backlog|Na urobenie|Rozrobené|Tím kontroluje|Čaká na tvoj test|Pre tím|Hotovo","pitch.words.few":"{n} slová","pitch.words.many":"{n} slova","pitch.letters.few":"{n} písmená","pitch.letters.many":"{n} písmena","pitch.chars.few":"{n} znaky","pitch.chars.many":"{n} znaku","count.line.html.few":"{n} karty sú práve na tabuli","count.line.html.many":"{n} karty je práve na tabuli","tl.cards.few":"{n} karty","tl.cards.many":"{n} karty","live.last.min.few":"Posledná karta presunutá pred {n} minútami","live.last.min.many":"Posledná karta presunutá pred {n} minúty","live.last.hour.few":"Posledná karta presunutá pred {n} hodinami","live.last.hour.many":"Posledná karta presunutá pred {n} hodiny","live.last.day.few":"Posledná karta presunutá pred {n} dňami","live.last.day.many":"Posledná karta presunutá pred {n} dňa"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegované."]},{"n":2,"texts":["Robotický kanban.","Agenti, usporiadaní.","Nápady hotovo."]},{"n":3,"texts":["Kanban pre robotov.","Z nápadov funkcie.","Bezplatný kanban agentov."]},{"n":5,"texts":["Kanban tabuľa, ktorú vedú agenti.","Ty píšeš karty. Agenti staviajú.","Zadarmo, lokálne, testované, trochu bláznivé."]},{"n":8,"texts":["Bezplatná kanban tabuľa, na ktorej pracujú AI agenti.","Napíš nápad. Agenti ho postavia. Ty ho schváliš.","Agilita pre jedného človeka a veľa trpezlivých robotov."]},{"n":13,"texts":["Kanban tabuľa na tvojom počítači, kde si karty preberajú AI agenti a pracujú na nich.","Napíš nápad. Tím agentov ho postaví. Tester ho skontroluje. Ty povieš áno.","Zadarmo, bez účtov a sledovačov: tabuľa, zopár robotov a ty ako šéf."]},{"n":21,"texts":["AI-gile je kanban tabuľa na prácu s AI agentmi, ktorí programujú. Oni preberajú karty a ty ich testuješ a schvaľuješ.","Každý projekt dostane vedúceho a tím AI agentov. Napíš komentár k ľubovoľnej karte a tím sa pustí do práce.","Bezplatná osobná tabuľa úloh, ktorá beží na tvojom vlastnom počítači. Pracujú na nej roboti. Povedať áno môžeš len ty."]},{"n":34,"texts":["Nápady dáš na tabuľu. Tím AI agentov ich premení na fungujúce funkcie, otestuje ich a vráti ti ich s krokmi na vyskúšanie. Nič nie je hotové, kým to nepovieš ty.","AI-gile je domáca kanban tabuľa, ktorú Rich postavil s veľkou pomocou agentov, ktorých dnes sama riadi. Je zadarmo, beží na tvojom počítači a zdieľa sa s priateľmi, nepredáva sa.","Predstav si obyčajnú kanban tabuľu so stĺpcami od Backlogu po Hotovo, len karty preberajú AI agenti. Hlásia pokrok, pýtajú sa, keď uviaznu, a vždy počkajú na tvoj súhlas."]},{"n":55,"texts":["AI-gile je kanban tabuľa, kde tím tvoria AI agenti. Každý projekt má vedúceho, ktorý plánuje prácu, a pomocníkov, ktorí ju stavajú. Keď je funkcia hotová, AI tester ju vyskúša a urobí snímku obrazovky, potom pristane na tvojej kôpke. Schváľ ju, alebo napíš komentár a prepracujú ju.","Začalo to ako spôsob, ako si jeden človek stráži veľa AI programátorských relácií naraz, a vyrástla z toho poriadna tabuľa. Beží na tvojom stroji, nepotrebuje účet a nemá sledovače. Pre priateľov a zvedavcov je zadarmo. Je aj nedokončená, takže počítaj s hranami a občasným prekvapením.","Tu je úprimná verzia. Nápady musíš stále mať ty a výsledky musíš stále skontrolovať ty. AI-gile robí všetko, čo je medzi tým: drží karty v poriadku, zobudí správneho agenta, keď napíšeš komentár, presne ukáže, čo sa zmenilo, a všetko ti zloží do jednej krátkej kôpky, ktorú zvládneš prejsť aj pri raňajšej káve."]},{"n":89,"texts":["AI-gile je bezplatná kanban tabuľa, ktorú spúšťaš na vlastnom počítači. Namiesto ľudí má každý projekt tím AI agentov: vedúceho, ktorý tvoje nápady premení na karty a plán, a pomocníkov, ktorí karty preberajú podľa priority. Keď je niečo postavené, AI tester prejde testovacie kroky a ukáže ti, čo videl. Potom to čaká v jednej kôpke s názvom Pre teba. Schválíš to, alebo napíšeš komentár a tím to skúsi znova. Do stĺpca Hotovo sa nič nedostane bez teba.","Niekoľko vecí, ktoré by ťa mohli prekvapiť. Nočná hliadka dopĺňa stĺpec Na urobenie, kým spíš, a vyberá karty, ktoré od teba nepotrebujú odpoveď. Počítadlo tokenov ukazuje, koľko agenti minuli dnes a tento týždeň, a Režim bez tokenov im povie, aby prestali míňať. S priateľmi si môžeš písať a súkromné správy sú šifrované end-to-end. Tabuľa hovorí približne 120 jazykmi, aj holandsky, flámsky, pirátsky a klingonsky. Nič z toho nestojí ani cent a nikto sa ti to ani nesnaží predať.","AI-gile je malý osobný projekt, nie firma. Rich chcel spravovať niekoľko AI programátorských projektov bez otvárania každej aplikácie, tak spolu s agentmi postavil tabuľu a potom na nej postavil zvyšok seba samej. Je v uzavretej pre-alfe, čo znamená, že pre hŕstku priateľov funguje, väčšinou. Nemá cenník, newsletter ani plán rastu. Beží na tvojom počítači, bez účtov a bez sledovačov. Ak ti to znie užitočne, môžeš si vyžiadať vyskúšanie, keď sa trochu viac otvorí. Napíšeme ti jediný e-mail, nič iné."]},{"n":144,"texts":["AI-gile je kanban tabuľa pre jedného človeka a veľa AI agentov. Beží na tvojom vlastnom počítači a je úplne zadarmo. Pridáš projekty a každý dostane vedúceho a malý tím. S vedúcim chatuješ, trochu ako na Discorde, a opíšeš nápad; vedúci z neho spraví karty a plán a potom čaká, kým stlačíš Ísť na to. Tím prechádza karty podľa priority pomocou jednoduchého príkazového riadku vytvoreného pre jazykové modely. Skôr než sa čokoľvek vráti k tebe, AI tester prejde kroky v kópii aplikácie a priloží snímku obrazovky. Hotová práca pristane na tvojej kôpke so zmenenými súbormi a rozdielmi. Schválíš ju, alebo zanecháš komentár a tím sa zobudí a skúsi to znova. Kartu do Hotovo môžeš presunúť len ty.","Deň s AI-gile, zhruba. Večer necháš pár komentárov: toto tlačidlo je na zlom mieste, ten zoznam by mal byť zoradený, mohli by sme mať tmavý režim. Ideš spať. Agenti si prečítajú komentáre, urobia zmeny, otestujú ich a vrátia ti ich. Ak Na urobenie vyschne, nočná hliadka ho doplní z backlogu kartami, ktoré od teba nepotrebujú odpoveď. Ráno je tu jedna krátka kôpka: pár otázok a zopár vecí na vyskúšanie, každá s krokmi, ktoré zvládne aj rozospatý človek, a so snímkou, že to funguje. Prekliknieš sa, schváliš dobré a zvyšok pošleš späť. Počítadlo tokenov ukáže, čo to všetko stálo, a Režim bez tokenov je tu na skromnejšie týždne. Potom si dáš raňajky, v ktorých ti agenti zatiaľ pomôcť nevedia.","Najprv to, čo AI-gile nie je. Nie je to startup, nie je na predaj a nikto nezbiera tvoje dáta. Je to bezplatná tabuľa, ktorá beží na tvojom počítači, bez účtov, bez sledovačov a bez cookies. A čo to je: jedno prehľadné miesto, kde vidíš všetky AI programátorské projekty naraz, s tímom agentov, ktorý robí karty, a tebou, ktorý rozhoduješ. Zlučuje súvisiace karty, opravuje zmätené názvy a pozerá, aby kód zostal štíhly. Hovorí približne 120 jazykmi, od holandčiny a flámčiny po pirátčinu a klingončinu. Priatelia si môžu písať súkromne a šifrovane. Postavil ho Rich s veľkým počtom trpezlivých agentov, väčšinou za pomoci seba samého. Je v uzavretej pre-alfe, takže miestami drhne. Ak ti to znie zábavne, pekne požiadaj a možno sa dostaneš dnu skôr."]}],"quips":{"1":"Jedno slovo. Odvážne. Možno príliš.","3":"Tri slová. Už teraz úprimnejšie ako väčšina produktových stránok.","8":"Osem slov. Stále kratšie ako stand-up.","21":"Dĺžky sú mimochodom story pointy. Samozrejme, že sú.","55":"Päťdesiatpäť slov. Kým si to čítal, dokončili sa dve karty.","144":"To je tá dlhá. 233 neexistuje. Agenti išli spať."}},"timeline":{"first-idea.name":"Prvý nápad","first-idea.line":"Úplne prvý rozhovor, ešte pred prvým riadkom kódu.","first-board.name":"Prvá tabuľa","first-board.line":"Tabuľa, ktorá sleduje vlastnú stavbu: karty, stĺpce, presúvanie, projekty.","team-roles.name":"Tím a roly","team-roles.line":"Profily agentov, šablóny tímov, priestory a kto robí čo.","install.name":"Inštalácia a vydania","install.line":"Zip, ktorý si nainštaluje aj kamarát, samoaktualizácie, kanály a návrat späť.","usage-saver.name":"Šetrič spotreby","usage-saver.line":"Zmeraj, koľko behy stoja, udržuj kód štíhly, šetri svoj limit.","friends.name":"Priatelia a zdieľanie","friends.line":"Súkromné správy, šifrované relé, pozvánky, roly a zdieľané projekty.","languages.name":"Jazyky","languages.line":"Každý text obrazovky v jazykovom súbore, najprv holandčina a flámčina.","ai-tester.name":"AI tester","ai-tester.line":"Tester najprv skontroluje každé odovzdanie a ukáže, čo videl.","website.name":"Web","website.line":"aigile.lol, ukážka a táto časová os.","streaming.name":"Chat a streamovanie","streaming.line":"Discord, Twitch, OBS, režim streamera, GIFy a emoji.","no-ai.name":"Edícia bez AI","no-ai.line":"Tabuľa pre ľudí, ktorí programujú bez AI, a verejné tabule.","night-watch.name":"Nočná hliadka","night-watch.line":"Strážca a Scrum Master držia tímy pri práci, kým spíš.","p-more.name":"Všetko ostatné","p-more.line":"Menšie nápady, ktoré čakajú na rad.","p-android.name":"Telefón a Android","p-android.line":"Tabuľa z telefónu a potom natívna aplikácia pre Android.","p-release.name":"Alfa a ďalej","p-release.line":"Uzavretá alfa, živý web a potom beta.","p-languages.name":"Viac jazykov","p-languages.line":"Viac než sto jazykov a imerzný režim pre študentov.","p-engines.name":"Viac AI motorov","p-engines.line":"Vyber Claude, Codex alebo Gemini pre každého agenta.","p-pro.name":"Profesionálna prax","p-pro.line":"Štítky rizika, brány zlúčenia, karty incidentov a zábradlia.","p-self.name":"Starostlivosť o teba","p-self.line":"Režim únavy, pripomienky starostlivosti o seba a 4:20.","p-servers.name":"Servery a rast","p-servers.line":"Globálne nastavenia servera, roly a plánovanie rastu.","p-livestream.name":"Streamovacie doplnky","p-livestream.line":"Twitch chat, vlastné emoji a verejný živý pohľad."},"words":{"button":"📖 Vývojárske slová","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Hľadať slovo…","none":"Také slovo sa nenašlo.","close":"Zavrieť","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Priečinok projektu s kódom a celou históriou commitov, zvyčajne uložený aj na GitHube.","also":["repozitár","repozitára"]},{"id":"branch","g":"build","word":"Branch","text":"Samostatná línia práce v kóde, aby sa dali robiť zmeny bez dotyku hlavnej verzie.","also":["branche","vetva","vetvy"]},{"id":"commit","g":"build","word":"Commit","text":"Uložený snímok kódu s krátkou poznámkou o tom, čo sa zmenilo. Vždy sa k nemu dá vrátiť.","also":["commity","commitu","commitov"]},{"id":"push","g":"build","word":"Push","text":"Odoslanie uložených snímkov (commitov) z tohto počítača na GitHub, aby boli zálohované a zdieľané."},{"id":"merge","g":"build","word":"Merge","text":"Zlúčenie zmien z vetvy späť do hlavnej verzie."},{"id":"pr","g":"build","word":"Pull request","text":"Žiadosť o kontrolu a zlúčenie zmien z vetvy do hlavnej verzie.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoring","text":"Upratovanie kódu bez zmeny toho, čo robí: menšie súbory, jasnejšie názvy, menej opakovania."},{"id":"bug","g":"build","word":"Bug","text":"Niečo, čo nefunguje tak, ako má.","also":["bugy","bugu"]},{"id":"test","g":"build","word":"Test","text":"Vyskúšanie hotovej práce, aby sa overilo, že robí, čo sa žiadalo, ešte než ju prijmeš.","also":["testy","testu","testovanie","testovať"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Nasadenie novej verzie naživo, napríklad na server, kde ju ľudia používajú."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Nápady a práca, ktoré ešte nie sú naplánované. Nič z toho sa nerobí, kým sa to nepresunie do stĺpca Na urobenie."},{"id":"sprint","g":"team","word":"Sprint","text":"Krátke obdobie práce (často týždeň či dva) s dohodnutou sadou kariet, ktoré treba dokončiť.","also":["sprinty","sprintov","sprintu"]},{"id":"standup","g":"team","word":"Stand-up","text":"Rýchle stretnutie: čo kto urobil, čo bude robiť ďalej a čo mu bráni.","also":["standup","stand-upy","stand-upu"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board so stĺpcami (Na urobenie, Rozrobené, Hotovo), na ktorom sa karty presúvajú zľava doprava, ako práca pokračuje."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: maximálny počet kariet v stĺpci, aby tím veci dokončoval skôr, než začne ďalšie.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI, ktorá pracuje na úlohe sama: číta kód, robí zmeny, spúšťa kontroly a hlási späť.","also":["agenti","agentov"]},{"id":"token","g":"team","word":"Token","text":"Jednotka, v ktorej sa počíta využitie AI: zhruba pár písmen prečítaného alebo napísaného textu. Čím menej tokenov, tým viac z plánu ostane.","also":["tokeny","tokenov"]},{"id":"hook","g":"team","word":"Hook","text":"Malý príkaz, ktorý sa sám spustí v určitom okamihu, napr. keď sa začne relácia AI, aby tím počul tvoje komentáre.","also":["hooky","hooku"]}]}};
